# --- Botanical engine merge (petey_muse_botanical_engine v2.4.0) ---
# Attaches the engine's 10-node knowledge graph to the seed WITHOUT touching
# any verified_* field, verification_status, toxicity_status, notes, or
# numeric game-model parameter: engine numbers land only in engine_* fields
# and are labeled "petey_muse_botanical_engine v2.4.0 parameters".
# Dedupe key: accepted name (+ cultivar). 7 nodes attach to existing records;
# 3 are genuinely new records. Correction to the integration brief: the brief
# claimed Goeppertia makoyana and Phalaenopsis aphrodite already existed in
# the seed — neither name appears in the pre-merge seed, so both are added
# here as new records (dedupe by accepted name proves they are new).
# New records copy NUMERIC parameters from the nearest existing template
# record (this file's established "family template" practice) and keep every
# verified field empty — they add engine parameters, not verified facts.

_ENGINE_SOURCE = "petey_muse_botanical_engine v2.4.0 parameters"


def _engine_profile_dict(profile) -> dict:
    values = dataclasses.asdict(profile)
    return {k: (v.value if isinstance(v, enum.Enum) else v) for k, v in values.items()}


def _attach_engine_node(record, node, notes: str) -> None:
    record.engine_taxon_code = node.taxon_code
    record.engine_plantnet_species_id = node.plantnet_species_id
    record.engine_care_cluster_id = node.care_cluster_id
    record.engine_photosynthetic_pathway = node.pathway.value
    record.engine_life_form = node.life_form.value
    record.engine_root_architecture = node.root_architecture.value
    record.engine_substrate = node.hydraulics.substrate.value
    record.engine_toxicity_mechanism = node.toxicity.value
    record.engine_photobiology = _engine_profile_dict(node.photobiology)
    record.engine_thermodynamics = _engine_profile_dict(node.thermodynamics)
    record.engine_hydraulics = _engine_profile_dict(node.hydraulics)
    record.engine_npk_ratio = list(node.npk_stoichiometry_ratio)
    record.engine_source = _ENGINE_SOURCE
    record.engine_notes = notes


def _apply_engine_merge() -> None:
    graph = _build_engine_graph()
    by_name = {}
    for rec in SPECIES:
        by_name.setdefault(rec.scientific_name, rec)
    # 7 overlaps: attach engine parameters to the FIRST record of that name.
    overlaps = {
        "Monstera deliciosa": ("ARA-MON-DEL-001", "Engine node is the species type; no cultivar."),
        "Dracaena trifasciata": ("ASP-DRA-TRI-001", "Engine node is the 'Laurentii' cultivar; species record keeps its own cultivar field."),
        "Zamioculcas zamiifolia": ("ARA-ZAM-ZAM-001", ""),
        "Ficus lyrata": ("MOR-FIC-LYR-001", ""),
        "Peperomia obtusifolia": ("PIP-PEP-OBT-001", ""),
        "Spathiphyllum wallisii": ("ARA-SPA-WAL-001", ""),
        "Crassula ovata": ("CRA-CRA-OVA-001", ""),
    }
    for name, (code, note) in overlaps.items():
        _attach_engine_node(by_name[name], graph[code], note)

    def _template(name):
        t = by_name[name]
        return (t.crop_coeff_k, t.min_soil_moisture_pct, t.max_soil_moisture_pct,
                t.ideal_vpd_min_kpa, t.ideal_vpd_max_kpa, t.min_lux, t.optimal_lux,
                list(t.soil_ph_range), list(t.common_pathogens))

    # 3 new records: numeric parameters copied from the nearest template
    # record; verified fields stay empty; toxicity_status stays "unverified"
    # with a note that the engine mechanism is a model parameter, not a
    # verified source. The cultivar record uses its full accepted name
    # (the engine node's wcvp_accepted_name) as scientific_name, so it
    # never collides with the species record in name-keyed stores — the
    # KB's scientific_name PRIMARY KEY would otherwise collapse the two
    # rows and let the cultivar overwrite the species entry.
    monstera = _template("Monstera deliciosa")
    thai = _s("Monstera deliciosa 'Thai Constellation'", "Thai Constellation Monstera", "Araceae", A01,
              monstera[0], monstera[1], monstera[2], monstera[3], monstera[4],
              monstera[5], monstera[6], monstera[7], True, monstera[8],
              cultivar="Thai Constellation",
              notes="Engine cultivar record (ARA-MON-DEL-002), distinct from the species record. Numeric parameters are approximate, copied from the Monstera deliciosa template (not verified for this cultivar). Engine photobiology applies a 0.74 variegation chlorophyll penalty.",
              tox_note="Toxicity bool follows the parent species' calcium-oxalate mechanism (engine model parameter); no cultivar-specific source was verified, so toxicity_status stays unverified.")
    _attach_engine_node(thai, graph["ARA-MON-DEL-002"], "Variegated chimeral cultivar; 0.74 variegation chlorophyll penalty.")
    SPECIES.append(thai)
    orbifolia = _template("Goeppertia orbifolia")
    makoyana = _s("Goeppertia makoyana", "Peacock Plant", "Marantaceae", A07,
                  orbifolia[0], orbifolia[1], orbifolia[2], orbifolia[3], orbifolia[4],
                  orbifolia[5], orbifolia[6], orbifolia[7], False, orbifolia[8],
                  notes="Engine record (MAR-GOE-MAK-001). Synonym: Calathea makoyana. Numeric parameters are approximate, copied from the Goeppertia orbifolia template (not verified for this species).",
                  tox_note="Engine mechanism is non-toxic pet-safe (model parameter, not a verified source); toxicity_status stays unverified.")
    _attach_engine_node(makoyana, graph["MAR-GOE-MAK-001"], "Fluoride/boron-sensitive Marantaceae; engine toxicity mechanism is a model parameter.")
    SPECIES.append(makoyana)
    amabilis = _template("Phalaenopsis amabilis")
    aphrodite = _s("Phalaenopsis aphrodite", "Moth Orchid", "Orchidaceae", A10,
                   amabilis[0], amabilis[1], amabilis[2], amabilis[3], amabilis[4],
                   amabilis[5], amabilis[6], amabilis[7], False, amabilis[8],
                   notes="Engine record (ORC-PHA-APH-001), distinct from Phalaenopsis amabilis. Numeric parameters are approximate, copied from the Phalaenopsis amabilis template (not verified for this species).",
                   tox_note="Engine mechanism is non-toxic pet-safe (model parameter, not a verified source); toxicity_status stays unverified.")
    _attach_engine_node(aphrodite, graph["ORC-PHA-APH-001"], "CAM epiphyte with velamen roots; engine toxicity mechanism is a model parameter.")
    SPECIES.append(aphrodite)


_apply_engine_merge()


def ingest_json_dump(path: str) -> List[Species]:
    """STUB (documented, not executed): ingest a larger species JSON dump later.

    Expected format: a JSON list of objects with exactly the Species fields
    (scientific_name, common_name, family, archetype_rig_id, crop_coeff_k,
    min/max_soil_moisture_pct, ideal_vpd_min/max_kpa, min/optimal_lux,
    soil_ph_range, pet_toxicity, common_pathogens). Callers should validate
    each record with Species(**record) and append to SPECIES. This function
    is intentionally not called at import time and performs no download.
    """
    with open(path, "r", encoding="utf-8") as fh:
        raw = json.load(fh)
    return [Species(**record) for record in raw]


def _history(rng: random.Random, start_moisture: float, vpd_base: float,
             temp_base: float, rh_base: float, lux_base: float,
             force_low_vpd_tail: bool = False) -> List[HistoryEntry]:
    entries: List[HistoryEntry] = []
    moisture = start_moisture
    today = date.today()
    for i in range(30):
        d = today - timedelta(days=29 - i)
        # Deterministic random walk, clamped.
        moisture = max(5.0, min(95.0, moisture + rng.uniform(-6, 0)))
        vpd = round(max(0.1, vpd_base + rng.uniform(-0.2, 0.2)), 3)
        if force_low_vpd_tail and i >= 26:
            vpd = 0.30
        temp = round(temp_base + rng.uniform(-2, 2), 1)
        rh = round(max(20.0, min(95.0, rh_base + rng.uniform(-8, 8))), 1)
        lux = round(max(100.0, lux_base + rng.uniform(-300, 300)), 1)
        watered = (i % 7 == 3)
        if watered:
            moisture = min(95.0, moisture + 25.0)
        entries.append(HistoryEntry(
            date_iso=d.isoformat(), moisture_pct=round(moisture, 1), vpd_kpa=vpd,
            temp_c=temp, rh_pct=rh, lux=lux, watered=watered,
        ))
    return entries


def _plant(pid, name, common, scientific, family, arch, pot_mat, pot_type, hp, xp,
           streak, shields, moisture, vpd, lux, locked, lock_reason, mood, droop,
           particle, quests, history):
    return PlantState(
        id=pid, name=name, species_common_name=common,
        species_scientific_name=scientific, family=family, archetype_rig_id=arch,
        pot_material=pot_mat, pot_type=pot_type, hp=hp, xp=xp,
        level=1 + xp // 200, streak_days=streak, mulch_shields=shields,
        moisture_pct=moisture, vpd_kpa=vpd, lux=lux, watering_locked=locked,
        lock_reason=lock_reason,
        next_water_iso=(date.today() + timedelta(days=2)).isoformat(),
        mood=mood, droop_angle_deg=droop, particle_effect=particle,
        quests=quests, history=history,
    )


def build_demo_plants() -> List[PlantState]:
    """3 demo plants, each with 30 days of deterministic synthetic history."""
    rng = random.Random(42)
    monty_hist = _history(rng, 55.0, 1.1, 24.0, 55.0, 2500.0)
    callie_hist = _history(rng, 70.0, 0.8, 23.0, 70.0, 1500.0, force_low_vpd_tail=True)
    serp_hist = _history(rng, 45.0, 1.2, 25.0, 50.0, 2800.0)
    monty = _plant(
        "monty-monstera", "Monty", "Monstera", "Monstera deliciosa", "Araceae",
        "01_fenestrated_aroid", "terracotta", "round", 60, 340, 12, 1,
        monty_hist[-1].moisture_pct, monty_hist[-1].vpd_kpa, monty_hist[-1].lux,
        False, None, "worried", 18.0, "spider_mites",
        [Quest(id="q-monty-1", title="Treat the spider mites",
               description="Wipe Monty's leaves and isolate him from other plants.", xp_reward=50),
         Quest(id="q-monty-2", title="Water Monty",
               description="Water Monty when his soil dries out.", xp_reward=20)],
        monty_hist)
    callie = _plant(
        "callie-calathea", "Callie", "Orbifolia Prayer Plant", "Goeppertia orbifolia",
        "Marantaceae", "07_prayer_foliage", "ceramic", "round", 45, 180, 5, 0,
        callie_hist[-1].moisture_pct, callie_hist[-1].vpd_kpa, callie_hist[-1].lux,
        True, "Root-rot brake: VPD below 0.4 kPa sustained 4+ days — watering locked to prevent root rot.",
        "drowning", 27.0, "raincoat",
        [Quest(id="q-callie-1", title="Let Callie dry out",
               description="Do not water Callie until the brake lifts; let soil dry.", xp_reward=50),
         Quest(id="q-callie-2", title="Improve airflow",
               description="Move Callie somewhere with better air circulation.", xp_reward=30)],
        callie_hist)
    serp = _plant(
        "serpentina-snake", "Serpentina", "Snake Plant", "Dracaena trifasciata",
        "Asparagaceae", "08_upright_sword", "stone", "tall", 94, 620, 21, 2,
        serp_hist[-1].moisture_pct, serp_hist[-1].vpd_kpa, serp_hist[-1].lux,
        False, None, "thriving", 3.0, "sparkles",
        [Quest(id="q-serp-1", title="Keep the streak alive",
               description="Check in on Serpentina daily to keep her streak going.", xp_reward=20),
         Quest(id="q-serp-2", title="Share a photo",
               description="Take a photo of Serpentina in bright light.", xp_reward=30)],
        serp_hist)
    return [monty, callie, serp]
